import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading
const { fontFamily: montserratFamily } = loadMontserrat();



export type SequentialCounterProps = Record<string, any>;

const SequentialCounter: React.FC<SequentialCounterProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 3,
  barColor = "#1a1a24",
  textColor = "#ffffff",
  sequenceItems = ["80 lbs", "90 lbs", "100+ lbs"],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Responsive baseline
  const s = Math.min(width, height);

  // Background logic
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Animation constants
  const totalFrames = durationInSeconds * fps;
  const itemCount = Math.max(1, sequenceItems.length);
  const itemDuration = totalFrames / itemCount;

  // Continuous upward drift for the entire container to give "upward momentum"
  const barFloat = interpolate(frame, [0, totalFrames], [s * 0.08, -s * 0.08], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Initial pop-in scale of the dark bar
  const barScale = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8, stiffness: 120 },
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: montserratFamily,
      }}
    >
      <div
        style={{
          backgroundColor: barColor,
          borderRadius: s * 0.1,
          padding: `${s * 0.035}px ${s * 0.08}px`,
          display: "grid",
          placeItems: "center",
          overflow: "hidden",
          transform: `scale(${barScale}) translateY(${barFloat}px)`,
          boxShadow: "0px 24px 48px rgba(0, 0, 0, 0.4)",
        }}
      >
        {sequenceItems.map((item, i) => {
          const enterFrame = i * itemDuration;
          const exitFrame = (i + 1) * itemDuration;
          const isLast = i === sequenceItems.length - 1;

          // Springs for position (allows subtle bouncing)
          const entranceSpring = spring({
            frame: frame - enterFrame,
            fps,
            config: { damping: 10, mass: 0.8, stiffness: 140 }, // Bouncy
          });

          const exitSpring = isLast
            ? 0
            : spring({
                frame: frame - exitFrame,
                fps,
                config: { damping: 14, mass: 0.8, stiffness: 120 }, // Smoother exit
              });

          // Linear interpolation for opacity (prevents flicker from spring overshoots)
          const opacityFadeIn = interpolate(
            frame - enterFrame,
            [0, 10],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          const opacityFadeOut = isLast
            ? 0
            : interpolate(frame - exitFrame, [0, 10], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });

          const opacity = Math.max(0, Math.min(1, opacityFadeIn - opacityFadeOut));

          // Calculate Y position: enters from bottom, exits to top
          const slideDistance = s * 0.15;
          const translateY =
            interpolate(entranceSpring, [0, 1], [slideDistance, 0]) +
            interpolate(exitSpring, [0, 1], [0, -slideDistance]);

          return (
            <div
              key={i}
              style={{
                gridArea: "1 / 1", // Stacks all items directly on top of each other
                opacity: opacity,
                transform: `translateY(${translateY}px)`,
                color: textColor,
                fontSize: s * 0.09,
                fontWeight: 800,
                whiteSpace: "nowrap",
                letterSpacing: "-0.02em",
                willChange: "transform, opacity",
              }}
            >
              {item}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default SequentialCounter;